# Caroline B. Brettell, Following Father Chiniquy: Immigration, Religious Schism, and Social Change in
# Nineteenth-Century Illinois (Carbondale, Southern Illinois University Press, 2015), epub du Drive de l'auteur
# (dossier CHINIQUY). Corpus « Recherches », préfixe BR15.
from commun import Corpus
BR = "Brettell, Caroline B. (2015), Following Father Chiniquy: Immigration, Religious Schism, and Social Change in Nineteenth-Century Illinois, Carbondale, Southern Illinois University Press"
C = Corpus('Recherches', 'BR15', BR, page_fmt='{}')
F = C.F
SA = (-87.714, 41.025)
F('01', "Sainte-Anne (Illinois) : l'église catholique du père Letellier rebâtie face aux presbytériens de Chiniquy (1871-1885)", 'religion', '1871-10/1885-06-18', SA[0]+0.003, SA[1]+0.002, 'c', ['Michel Letellier', 'Ambroise Allain', 'Antoine Allain', 'Charles Chiniquy'],
  "Après le schisme, les catholiques de Sainte-Anne doivent aller prier à Sainte-Marie (Beaverville), à dix milles. En 1871, le père Michel Letellier est envoyé reconquérir la paroisse : l'église est achevée en 1872 au point le plus haut du village, sur une terre des frères Ambroise et Antoine Allain, établis avant l'arrivée de Chiniquy. La souscription de 4 500 $ tourne mal et une dette de 7 000 $ subsiste dix ans plus tard ; Letellier note avec soin les noms des schismatiques revenus au catholicisme. En 1872-1873, la Première Église presbytérienne de Chiniquy compte pourtant 150 familles et 210 communiants. Le 18 juin 1885, la Kankakee Gazette dénombre 23 attelages devant l'église catholique contre 16 et 9 devant les deux églises presbytériennes.",
  "ch. 6", "Position approximative de l'église Sainte-Anne.")
F('02', "Sainte-Anne (Illinois) : relique de sainte Anne et pèlerinage des Canadiens du Midwest (1880-1939)", 'religion', '1881~/1939', SA[0]+0.0035, SA[1]+0.0015, 'c', ['Bourassa (abbé)', 'Matilda Cunnea', 'Lucille Walsh', 'E. L. Rivard'],
  "Calquée sur Sainte-Anne-de-Beaupré, une neuvaine attire chaque juillet les Canadiens français du Midwest ; en 1889, un train spécial de dix voitures amène de Chicago un millier de pèlerins, logés à l'académie Sainte-Anne ouverte en 1883 par les sœurs de Notre-Dame. Après la foudre de 1893, l'église est rebâtie et reçoit en 1894, à la demande de l'abbé Bourassa de Pullman, une relique (un os de la main) envoyée de Rome par le cardinal de Québec. Le 24 juillet 1904, Matilda Cunnea, paralysée depuis deux ans, se lève de son fauteuil, conservé depuis dans une chapelle latérale ; d'autres guérisons suivent jusqu'en 1912. En 1906, on compte 5 500 pèlerins. Le Viatorien E. L. Rivard y voit une réparation du schisme de Chiniquy.",
  "ch. 6", "La 105e neuvaine est célébrée en 1985.")
F('03', "Concordia (Kansas) : Mme Moïse Mercier, pèlerine guérie à Sainte-Anne (Illinois) (1910)", 'religion', '1910-07', -97.662, 39.571, 'a', ['Moïse Mercier (Mme)', 'Clément Lavoie (Mme)'],
  "Lors du pèlerinage de 1910, qui réunit deux mille personnes, Mme Moïse Mercier, de Concordia (Kansas), recouvre l'ouïe et Mme Clément Lavoie, de Sainte-Anne, jette ses béquilles : deux femmes d'ascendance canadienne-française, signe que la dévotion rayonnait jusqu'aux colonies canadiennes du Kansas.",
  "ch. 6", "Position à Concordia, foyer canadien-français du comté de Cloud.")
# Ajout du 19 nov. 2026 (soir) : relecture des chapitres 1 à 5 (seul le chapitre 6 avait été exploité).
F('04', "Cap-Saint-Ignace : 205 paroissiens partent pour l'Illinois en 1848", 'migration', '1848', -70.465, 47.033, 'c', ['J. N. Bossé'],
  "Le procureur québécois J. N. Bossé rapporte au gouvernement que 205 personnes ont quitté la paroisse de Cap-Saint-Ignace pour l'Illinois en 1848. Elles s'établissent à Bourbonnais, où elles achètent ou louent de quinze à quarante acres, en partie à Noël LeVasseur, revenu au Canada après 1837 inciter ses compatriotes à le suivre. Le gouvernement note que les gens de Bellechasse, de L'Islet et de Kamouraska vendent leurs terres pour l'Ouest, gagnant Chicago par les canaux et les lacs.",
  "ch. 1", "")
F('05', "Bourbonnais : les lettres de Peter Spink, le premier curé René Courjeault (1847) et le recensement de 1850", 'religion', '1845-09/1850', -87.879, 41.148, 'c', ['Peter Spink', 'René Courjeault', 'William Quarter', 'Noël LeVasseur'],
  "En septembre 1845, Mgr William Quarter, premier évêque de Chicago, demande à Mgr Bourget un prêtre pour les Canadiens de l'Illinois ; Peter Spink, Canadien d'origine écossaise de Bourbonnais, insiste en écrivant qu'une cinquantaine de familles y vivent sans prêtre parlant français (mars 1846 : onze familles de plus). Le premier curé résident, René Courjeault, arrive en mai 1847 : il compte 59 familles, puis 108 à l'automne. En 1850, 201 des 248 familles du canton de Bourbonnais (81 %) sont canadiennes-françaises, sur 1 720 habitants.",
  "ch. 1", "")
F('06', "Beaver Creek devient Sainte-Anne : les frères Allain, quarante cabanes et la chapelle bénie par Mgr Van de Velde (1850-1857)", 'etablissement', '1850/1857-04', SA[0], SA[1], 'c', ['Michel Allain', 'Ambroise Allain', 'Antoine Allain', 'Charles Chiniquy', 'Jacques Olivier Van de Velde', 'John B. Lemoine', 'Achille Chiniquy', 'Camille Betourni'],
  "En 1850, Michel Allain quitte Bourbonnais pour Beaver Creek avec ses fils Ambroise et Antoine, à qui il cède 160 acres le 21 juillet 1851. Chiniquy arrive en novembre 1851 : fin janvier 1852, quarante cabanes sont bâties, et en avril Mgr Van de Velde bénit une chapelle de quarante pieds carrés dédiée à sainte Anne. Ambroise Allain fils, né le 18 avril 1852, est le premier enfant blanc né à Sainte-Anne. En trois ans, de neuf cents à mille familles du Québec et de la Nouvelle-Angleterre s'établissent sur quarante milles carrés. La paroisse est érigée en 1853, une école de garçons ouvre en octobre 1855 ; le canton, créé en 1857, élit pour superviseur John B. Lemoine, pour percepteur Achille Chiniquy et pour constable Camille Betourni.",
  "ch. 1", "")
F('07', "Papineau (ancien canton de Weygandt) : choléra de 1855, scierie Delude et incorporation de 1874", 'etablissement', '1855/1874', -87.716, 40.968, 'c', ['Joseph Delude', 'Fabian Langdoc', 'C. P. Lottinville', 'Joseph Laveaux', 'Octave Laplante', 'Ezra Savoie'],
  "Le canton de Weygandt, peuplé de Hollandais dans les années 1840, perd la moitié de ses habitants dans le choléra de 1855 ; les Canadiens français qui l'envahissent le rebaptisent Papineau, du nom du héros patriote. Joseph Delude y bâtit une scierie ; une école ouvre en 1861, une église catholique en 1872 (démolie depuis). Le village est incorporé en 1874 : président Fabian Langdoc, greffier C. P. Lottinville, trésorier Joseph Laveaux, administrateurs Thomas Lottinville, Octave Laplante, Ezra Savoie et John Massey (Massé).",
  "ch. 1", "")
F('08', "Sainte-Marie (Beaverville) : premiers colons au printemps 1853 et village loti sur la terre de Charles Arseneau (1859)", 'etablissement', '1853/1859', -87.656, 40.953, 'c', ['Charles Arseneau', 'Joseph Caillouette', 'Joseph Lottinville'],
  "Dans le nord du canton de Beaver, déserté par des Norvégiens décimés par le choléra, les Canadiens français fondent Sainte-Marie, à la limite du canton de Papineau. Les premiers colons (Arseneau, Boudreau, Benoit, Dionne, Fortin, Lafond, Nourie) arrivent au printemps 1853 ; Joseph Caillouette bâtit la première maison en 1857, et le village est loti en 1859 sur la terre de Charles Arseneau. En avril 1857, l'abbé Desaulniers y compte 115 familles hostiles à Chiniquy, auxquelles s'ajoutent vingt-cinq familles belges.",
  "ch. 1, 2", "")
F('09', "L'Érable : mission de Bourbonnais (1853-1854), chapelle Saint-Jean-Baptiste sur la terre de Spink (1854) et église de 1875", 'religion', '1853/1875', -87.905, 40.905, 'c', ['Peter Spink'],
  "L'Érable, nommé d'après les érables à sucre plantés par les premiers colons, naît en 1853-1854 comme mission de l'église de la Maternité de Bourbonnais. Peter Spink, l'adversaire de Chiniquy, y acquiert de grandes étendues qu'il revend aux arrivants ; en 1854, une chapelle dédiée à saint Jean-Baptiste est bâtie sur un terrain qu'il donne, et la Saint-Jean y est fêtée le 24 juin. Le village est loti en 1857 mais jamais incorporé ; l'église de bois encore debout est achevée en 1875. À la fin des années 1850, les Canadiens y sont dépassés en nombre par des immigrants de France.",
  "ch. 1", "")
F('10', "Urbana : le procès en diffamation de Peter Spink contre Chiniquy (1855-1856)", 'evenement', '1855-02-03/1856-10', -88.207, 40.111, 'c', ['Peter Spink', 'Charles Chiniquy'],
  "Spink accuse Chiniquy de l'avoir traité de parjure en chaire vers le 10 janvier 1854 et le poursuit le 3 février 1855 devant la cour de circuit du comté de Kankakee. Le procès est déplacé à Urbana (comté de Champaign) ; à la session de mai 1856, qui occupe presque les quatre jours de la cour et attire les partisans de Chiniquy, le jury ne parvient pas à un verdict. L'affaire se règle à l'amiable avant la session d'octobre, Chiniquy publiant une rétractation.",
  "ch. 2", "")
F('11', "Kankakee : l'assemblée du 27 avril 1857, le banquet de deux mille personnes pour l'abbé Desaulniers et l'évêque O'Regan brûlé en effigie", 'evenement', '1857-04-27/1857-11', -87.861, 41.120, 'c', ['Isaac Desaulniers', 'Anthony O\'Regan', 'Alexis Mailloux', 'Peter Spink', 'Joseph Lottinville'],
  "Le 27 avril 1857, une assemblée des Canadiens de Kankakee résout que les prêtres du Canada devraient s'occuper de leur pays plutôt que de semer la discorde aux États-Unis. En juin, un banquet tempérant de près de deux mille personnes honore l'abbé Isaac Desaulniers, « qui a réduit M. Chiniquy à l'impuissance » ; Spink, « fondateur de la colonie de L'Érable », et Joseph Lottinville, de Sainte-Marie, y prennent la parole, et un défilé aux chevaux décorés parcourt la ville. Le grand vicaire de Québec Alexis Mailloux lui succède ; l'évêque O'Regan démissionne en août et, en novembre, apprend qu'on l'a brûlé en effigie à Kankakee.",
  "ch. 2", "")
F('12', "Sainte-Anne : l'excommunication prononcée par Mgr Duggan (3 août 1858) et la rupture de Chiniquy (22 août)", 'religion', '1858-08-03/1858-08-22', SA[0]+0.001, SA[1]-0.001, 'c', ['Charles Chiniquy', 'James Duggan'],
  "Fin juillet 1858, le nouvel évêque de Chicago, James Duggan, se rend à Sainte-Anne pour mettre fin au schisme ; menacé par les partisans de Chiniquy, il doit demander la protection du shérif. Le 3 août, il prononce deux fois l'excommunication au milieu des huées. Le 22, Chiniquy rompt formellement, disant que l'évêque lui demande « non un acte de soumission, mais d'adoration ».",
  "ch. 2", "")
F('13', "Sainte-Anne et Kankakee : la « famine » de 1858-1859, l'aide presbytérienne et les deux Églises presbytériennes françaises (1859-1887)", 'religion', '1858/1887', SA[0]-0.001, SA[1]+0.001, 'c', ['Charles Chiniquy', 'Moses Staples', 'Theodore Monod', 'Achille Chiniquy'],
  "Après les mauvaises récoltes de 1858 et 1859, Chiniquy quête dans l'Est : fin novembre 1859, 8 000 $ en argent et une centaine de caisses de vêtements et de vivres sont expédiés en Illinois ; le 3 octobre 1859, l'église protestante de Kankakee est cédée à Moses Staples, agent de l'Assemblée générale presbytérienne, comme « Christian Catholic Church ». Début 1860, Chiniquy et une délégation sont reçus dans le presbytère de Chicago. En février 1861, une seconde Église presbytérienne se forme à Sainte-Anne sous Theodore Monod (89 familles en 1881) ; en 1862, l'Église de Chiniquy (550 personnes comptées) passe à un synode canadien. Les deux Églises se réunissent en 1887.",
  "ch. 2", "")
F('14', "Clyde (Kansas) : les enfants des colons de Sainte-Anne partent pour le Kansas (années 1870)", 'migration', '1870/1880', -97.401, 39.591, 'a', ['Antoine Allain fils', 'Jacques Boucher', 'Alexis Blanchette'],
  "Dans les années 1870, une partie de la génération née ou élevée à Sainte-Anne gagne le Kansas : Antoine Allain fils, fils d'un des premiers colons, est l'un des premiers ; Jacques Boucher, né à Nicolet en 1827, et plusieurs enfants d'Alexis Blanchette le suivent. Le mouvement reprend en 1878 quand le chemin de fer atteint la région de Clyde ; le Kankakee Gazette s'inquiète de tous ces départs vers des homesteads abandonnés par des Américains.",
  "ch. 4", "Brettell écrit « Clyde County » ; Clyde est dans le comté de Cloud.")
F('15', "Sainte-Anne : « le seul endroit des États-Unis où l'on ne parle que le français » (1873) et l'école de Chiniquy", 'evenement', '1856/1905', SA[0]+0.002, SA[1]-0.002, 'c', ['Charles Chiniquy', 'Francis Bechand', 'Michel Letellier'],
  "En 1860, 60 % des chefs de ménage sont inscrits comme illettrés. Une école est bâtie en 1856 à l'instigation de Chiniquy ; le premier maître, Francis Bechand, est engagé en 1857-1858. Le 11 septembre 1873, Chiniquy écrit dans le Kankakee Gazette que Sainte-Anne est sans doute le seul endroit des États-Unis où presque tout le monde ne parle que le français. L'enseignement du français cesse vers 1887 ; l'anglais entre à l'église protestante en 1885 et à l'église catholique en 1905, et l'académie catholique Sainte-Anne ouvre en 1884 avec les sœurs de la Congrégation de Notre-Dame de Montréal.",
  "ch. 5", "")
fiches = C.fiches
